"""Batch 1 practical-guide content for Panun Kaergar.

The HTML is intentionally a fragment: the guide page supplies its outer layout.
"""

from html import escape

from guide_image_utils import enrich_guide_images


def _article(item):
    """Build a complete, reusable article fragment from guide-specific reporting."""
    slug = item["slug"]
    enrich_guide_images(item)
    method_imgs = item.get("method_images", [])

    method_parts = []
    for number, ((heading, best_for, detail), img) in enumerate(
        zip(item["methods"], method_imgs), 1
    ):
        alt = img.get("alt", heading)
        cap = img.get("caption", heading)
        method_parts.append(
            f"""<div class="method" id="method-{number}">
  <span class="method-num">Method {number}</span>
  <h3>{escape(heading)}</h3>
  <p class="best-for">Best for: {escape(best_for)}</p>
  <p>{escape(detail)}</p>
  <figure class="figure"><img src="/images/guides/{slug}-method-{number}.webp" width="1200" height="675" alt="{escape(alt)}" loading="lazy" />
    <figcaption><strong>{escape(cap)}:</strong> {escape(detail.split('.')[0].strip())}</figcaption>
  </figure>
</div>"""
        )
    methods = "".join(method_parts)
    faqs = "".join(
        f"""<details><summary>{escape(question)}</summary>
  <p>{escape(answer)}</p>
</details>"""
        for question, answer in item["faqs"]
    )
    causes = "".join(f"<li>{escape(cause)}</li>" for cause in item["causes"])
    donts = "".join(f"<li>{escape(dont)}</li>" for dont in item["donts"])
    dont_heading = item.get("dont_heading", "What not to do")
    dont_intro = item.get("dont_intro", "<p>These shortcuts usually cost more than they save.</p>")
    dont_blocks = item.get("dont_blocks")
    if dont_blocks:
        dont_html = "".join(
            f"""<div class="method dont" id="dont-{n}">
  <span class="method-num">Don't {n}</span>
  <h3>{escape(title)}</h3>
  <p class="best-for">{escape(sub)}</p>
  <p>{escape(body)}</p>
  <figure class="figure"><img src="/images/guides/{slug}-dont-{n}.webp" width="1200" height="675" alt="{escape(alt)}" loading="lazy" />
    <figcaption><strong>{escape(cap)}:</strong> {escape(body.split('.')[0].strip())}</figcaption>
  </figure>
</div>"""
            for n, block in enumerate(dont_blocks, 1)
            for title, sub, body, alt, cap in [block[:5]]
        )
    else:
        dont_html = f"<ul>{donts}</ul>"
    service_slug = item.get("relatedServiceSlug") or ""
    service_label = SERVICE_HINTS.get(service_slug, "professional help")
    if service_slug == "carpentry":
        service_cta = (
            f'<p>Need hands-on help? Book verified '
            f'<a href="/services/carpentry">carpentry services in Kashmir</a> '
            f'or find a <a href="/near-me/carpenter-near-me">carpenter near you</a> '
            f'on Panun Kaergar when DIY has done its part.</p>'
        )
    elif service_slug:
        service_cta = (
            f'<p>Need hands-on help? Book verified '
            f'<a href="/services/{escape(service_slug)}">{escape(service_label)}</a> '
            f'through Panun Kaergar across Kashmir when DIY has done its part.</p>'
        )
    else:
        service_cta = ""
    return f"""<p class="scene">{escape(item["scene"])}</p>
<div class="answer-box"><span class="label">Quick answer</span><p>{escape(item["quickAnswer"])}</p></div>
<nav class="toc" aria-label="Table of contents"><p class="label">In this guide</p><ol>
  <li><a href="#diagnose">Quick diagnosis map</a></li><li><a href="#causes">What causes it</a></li>
  <li><a href="#methods">What to try first</a></li><li><a href="#kashmir">Kashmir home note</a></li>
  <li><a href="#dont">What not to do</a></li><li><a href="#prevent">Keep it from returning</a></li>
  <li><a href="#book">When to book help</a></li><li><a href="#faq">FAQs</a></li>
</ol></nav>
<h2 id="diagnose">Quick diagnosis map</h2>
<p>Start with the symptom, not the most dramatic fix. A small check now can save a cabinet, appliance, or Sunday afternoon.</p>
<div class="table-wrap"><table><thead><tr><th>What you notice</th><th>Likely reason</th><th>First move</th></tr></thead>
<tbody><tr><td><strong>{escape(item["symptom"])}</strong></td><td>{escape(item["diagnosis"])}</td><td>{escape(item["first_move"])}</td></tr>
<tr><td><strong>Problem worsens after use</strong></td><td>{escape(item["worse_cause"])}</td><td>Stop adding load; inspect safely.</td></tr>
<tr><td><strong>Heat, burning smell, leak, or sudden pain</strong></td><td>Safety issue, not a DIY puzzle</td><td>Switch off / isolate / get help.</td></tr></tbody></table></div>
<div class="callout warning"><span class="label">Stop here</span><p>{escape(item["warning"])}</p></div>
<h2 id="causes">What usually causes this</h2>
<p>{escape(item["cause_lead"])}</p><ul>{causes}</ul>
<h2 id="methods">Try these in order</h2>
<p>Begin with the reversible checks. The goal is a clean fix, not winning an argument with a stubborn household thing.</p>
<figure class="figure"><img src="/images/guides/{slug}-methods.webp" alt="{escape(item['methods_alt'])}" loading="lazy" /><figcaption><strong>Method ladder:</strong> start with the low-risk check and move up only when it earns its place.</figcaption></figure>
{methods}
<figure class="figure"><img src="/images/guides/{slug}-diagram.webp" alt="{escape(item['diagram_alt'])}" loading="lazy" /><figcaption><strong>Diagnosis:</strong> the part or pattern worth checking before replacing anything.</figcaption></figure>
<div class="callout pro"><span class="label">A pro's shortcut</span><p>{escape(item["pro_tip"])}</p></div>
<div class="review">"{escape(item["review"])}"<cite>— {escape(item["review_by"])}</cite></div>
<h2 id="kashmir">Kashmir home note</h2><p>{escape(item["kashmir_note"])}</p>
<h2 id="dont">{dont_heading}</h2>{dont_intro}{dont_html}
<h2 id="prevent">Keep it from returning</h2>
<figure class="figure"><img src="/images/guides/{slug}-tip.webp" alt="{escape(item['tip_alt'])}" loading="lazy" /><figcaption><strong>Prevention tip:</strong> {escape(item["prevention_caption"])}</figcaption></figure>
<p>{escape(item["prevention"])}</p>
<h2 id="book">When to book a professional</h2><p>{escape(item["book"])}</p>
{service_cta}
<h2 id="faq">FAQs</h2><div class="faq">{faqs}</div>"""

