def _seo_from_compact(title: str, service: str, first_move: str) -> str:
    service_label = SERVICE_HINTS.get(service, "professional help")
    lead = title.strip().rstrip("?")
    step = first_move.split(".")[0].strip()
    return (
        f"{lead} in Kashmir? {step}. Learn the safest first checks, the usual causes, "
        f"and when to book {service_label}."
    )


def _compact(
    ident, slug, title, category, service, scene, answer, symptom, diagnosis,
    causes, method_rows, quote, person, local_note, warning, book,
    hero="", excerpt="",
):
    """Keep the later batch entries specific while preserving the full article shape."""
    subject = title.split("?")[0].lower()
    return dict(
        id=ident, slug=slug, title=title, heroSub=hero or (answer.split(".")[0] + "."),
        excerpt=excerpt or f"{scene.split('.')[0]}. {answer.split('.')[0]}.",
        seoTitle=f"{title} | Panun Kaergar",
        seoDescription=_seo_from_compact(title, service, method_rows[0][2]),
        category=category, relatedServiceSlug=service, readingMinutes=9,
        scene=scene, quickAnswer=answer, symptom=symptom, diagnosis=diagnosis,
        first_move=method_rows[0][2], worse_cause="An underlying fault or hidden damage",
        warning=warning,
        cause_lead="The visible symptom is useful, but the small detail around it usually tells the real story.",
        causes=causes, methods=method_rows,
        methods_alt=f"Practical {subject} troubleshooting steps",
        diagram_alt=f"Diagnosis diagram for {subject}",
        pro_tip="Take one clear photo before taking anything apart. It helps a professional see the pattern and saves guesswork.",
        review=quote, review_by=person.split(",")[0].strip(), kashmir_note=local_note,
        donts=[
            "Force a part that is stuck or swollen.",
            "Use a stronger chemical or tool just because the first attempt failed.",
            "Ignore heat, smell, spreading damage, or a problem that returns quickly.",
        ],
        prevention="Fix the small trigger, keep the area clean and dry where relevant, and deal with repeat symptoms before they become a replacement job.",
        prevention_caption="A small regular check is cheaper than an emergency repair.",
        book=book,
        faqs=[
            (f"What is the first check for {subject}?", method_rows[0][2]),
            ("Can I keep using it?", "Only if there is no safety risk or spreading damage. Stop when the symptom worsens."),
            ("Why did this start suddenly?", "A change in load, moisture, wear, cleaning product, or season often exposes a weak point."),
            ("Will a temporary fix last?", "It can buy time, but repeat symptoms need the cause corrected."),
            ("When should I book help?", book),
        ],
        tip_alt=f"Simple prevention step for {subject}",
    )

